{
    "allegatiConfigurabili": {
        "listaAllegati": [],
        "nomeCampoControllo": [],
        "valoriAmmessiCampoControllo": []
    },
    "bloccoStep": {},
    "sottoscrittoLabel": "Il/la sottoscritto/a",
    "datiAnagrafici": {},
    "datiEnte": {},
    "dichiarazioni": {
        "dichiarazioniR0": "<ul> <li>che l'evento denominato </li></ul>",
        "eventoPeriodico": {},
        "dichiarazioniR1": "<ul><li>che le notizie relative al soggetto richiedente e all’iniziativa organizzata sono riportate nella istanza di ammissione al contributo;<li>che le spese riportate in allegato  sono state integralmente pagate ed afferiscono esclusivamente alla realizzazione dell’iniziativa sopra descritta;<li>di essere consapevole che la Regione Puglia può effettuare accertamenti, verifiche, richiedere ed acquisire le certificazioni opportune ed indispensabili per controllare quanto autocertificato;<li>ai sensi dell’art. 16 bis, comma 10, del D.L. 185/2008 conv. in  legge 28 gennaio 2009, n. 2 che (selezionare l’opzione che interessa)</li></ul>",
        "dichiarazioniR2": "<ul><li>che il soggetto organizzatore",
        "dichiarazioniR3": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;recuperare l’imposta sul valore aggiunto (IVA) prevista dal progetto e, pertanto, la stessa deve considerarsi quale spesa",
        "dichiarazioniR4": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;a finanziamento;</li></ul>",
        "dichiarazioniR5": "<ul> <li>che il soggetto organizzatore ",
        "dichiarazioniR6": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;soggetto alla ritenuta d’acconto del 4% ai sensi del D.P.R. 600/73 e successive modifiche ed integrazioni ; </li>",
        "dichiarazioniR7": "<ul><li>che, al fine dell’applicazione dell’art. 53 comma 16 ter del D.Lgs 165/2001, introdotto dalla Legge n. 190/2012 (attività successiva alla cessazione del rapporto di lavoro — pantouflage o revolving doors), l’associazione non ha concluso contratti di lavoro subordinato o autonomo e, comunque, non ha attribuito incarichi ad ex dipendenti dell’Amministrazione regionale, che hanno esercitato poteri autoritativi o negoziali per conto della Regione Puglia nei propri confronti, nel triennio successivo alla cessazione del rapporto di lavoro con la Regione Puglia;</li><li>che i soggetti a cui sono stati corrisposti emolumenti non rivestano la qualifica di socio e/o siano titolari di cariche sociali in seno alle associazioni coinvolte ;</li><li>di impegnarsi a fornire ogni eventuale chiarimento e/o documentazione che saranno richiesti dalla Regione Puglia;</li></ul>"
    },
    "datiContoCorrente": {
        "contoCorrenteLabel": "il conto corrente <b><u>intestato al soggetto organizzatore</u></b>, su cui dovrà essere eseguito il versamento del contributo assegnato: ",
        "denominazioneBancaLabel": "DENOMINAZIONE DELLA BANCA O BANCO POSTA*",
        "numAgenziaLabel": "INDICARE L’AGENZIA O L’UFFICIO POSTALE*",
        "ibanLabel": "CODICE IBAN*"
    },
    "stimaDeiCosti": {
        "descrizioneLabel": "Descrizione della spesa",
        "fatturaLabel": "Fattura o Ricevuta N.",
        "dataLabel": "Data",
        "imponibileLabel": "Imponibile",
        "ivaLabel": "Iva",
        "totaleLabel": "Totale",
        "dataPagamentoLabel": "Data pagamento",
        "modalitaLabel": "Modalità di pagamento",
        "bancaLabel": "Banca",
